import{_ as r,c as e,o as i,ak as o}from"./chunks/framework.CtX3_w5e.js";const c=JSON.parse('{"title":"Spring Cloud微服务：入门、实战与进阶","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"Spring Cloud微服务：入门、实战与进阶","hugoSource":"books/computer-science/Spring Cloud微服务：入门、实战与进阶.md","outline":[1,6]},"headers":[],"relativePath":"Books/computer-science/2026-11-17-Spring Cloud微服务：入门、实战与进阶.md","filePath":"Books/computer-science/2026-11-17-Spring Cloud微服务：入门、实战与进阶.md","lastUpdated":1794887319000}'),n={name:"Books/computer-science/2026-11-17-Spring Cloud微服务：入门、实战与进阶.md"};function t(a,l,s,u,g,d){return i(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="_1-3-什么是spring-cloud" tabindex="-1">1.3 什么是Spring Cloud <a class="header-anchor" href="#_1-3-什么是spring-cloud" aria-label="Permalink to “1.3 什么是Spring Cloud”">​</a></h3><ul><li><strong>Eureka</strong><ul><li>服务注册中心，用于服务管理</li></ul></li><li><strong>Ribbon</strong><ul><li>基于客户端的负载均衡组件</li></ul></li><li><strong>Hystrix</strong><ul><li>容错框架，能够防止服务的雪崩效应</li></ul></li><li><strong>Feign</strong><ul><li>Web服务客户端，能够简化HTTP接口的调用</li></ul></li><li><strong>Zuul</strong><ul><li>API网关，提供路由转发、请求过滤等功能</li></ul></li><li><strong>Config</strong><ul><li>分布式配置管理</li></ul></li><li><strong>Sleuth</strong><ul><li>服务跟踪</li></ul></li><li><strong>Stream</strong><ul><li>构建消息驱动的微服务应用程序的框架</li></ul></li><li><strong>Bus</strong><ul><li>消息代理的集群消息总线。</li></ul></li></ul><h2 id="第3章-eureka注册中心" tabindex="-1">第3章　Eureka注册中心 <a class="header-anchor" href="#第3章-eureka注册中心" aria-label="Permalink to “第3章　Eureka注册中心”">​</a></h2><ul><li>Spring Cloud Eureka是一个基于REST的服务，并且提供了基于Java的客户端组件，能够非常方便地<strong>将服务注册到Spring Cloud Eureka中进行统一管理</strong>。 <ul><li><strong>服务治理</strong>是微服务架构中必不可少的一部分，阿里开源的Dubbo框架就是针对服务治理的。服务治理必须要有一个注册中心，除了用Eureka作为注册中心外，我们还可以使用Consul、Etcd、Zookeeper等来作为服务的注册中心。</li><li>用过Dubbo的读者应该清楚，Dubbo中也有几种注册中心，比如基于Zookeeper、基于Redis等，不过用得最多的还是Zookeeper方式。至于使用哪种方式都是可以的，<strong>注册中心无非就是管理所有服务的信息和状态</strong>。</li><li>程序也是一样，<strong>当你需要调用某一个服务的时候，你会先去Eureka中去拉取服务列表，查看你调用的服务在不在其中，在的话就拿到服务地址、端口等信息，然后调用</strong>。</li><li>为什么Eureka比Zookeeper更适合作为注册中心呢？ <ul><li>主要是因为<strong>Eureka是基于AP原则构建的，而ZooKeeper是基于CP原则构建的</strong>。在分布式系统领域有个著名的CAP定理，即<strong>C为数据一致性；A为服务可用性；P为服务对网络分区故障的容错性</strong>。这三个特性在任何分布式系统中都不能同时满足，最多同时满足两个。</li><li>Zookeeper有一个Leader，而且在这个Leader无法使用的时候通过Paxos(ZAB)算法选举出一个新的Leader。这个Leader的任务就是保证写数据的时候只向这个Leader写入，Leader会同步信息到其他节点。通过这个操作就可以保证数据的一致性。</li><li>总而言之，想要保证AP就要用Eureka，想要保证CP就要用Zookeeper。Dubbo中大部分都是基于Zookeeper作为注册中心的。Spring Cloud中当然首选Eureka。</li></ul></li></ul></li></ul><h2 id="第4章-客户端负载均衡ribbon" tabindex="-1">第4章　客户端负载均衡Ribbon <a class="header-anchor" href="#第4章-客户端负载均衡ribbon" aria-label="Permalink to “第4章　客户端负载均衡Ribbon”">​</a></h2><ul><li>目前主流的负载方案分为两种：一种是<strong>集中式负载均衡</strong>，在消费者和服务提供方中间使用独立的代理方式进行负载，有硬件的（比如F5），也有软件的（比如Nginx）。另一种则是客户端自己做负载均衡，根据自己的请求情况做负载，<strong>Ribbon就属于客户端自己做负载</strong>。</li><li>Ribbon作为一款客户端负载均衡框架，<strong>默认的负载策略是轮询</strong>，同时也提供了很多其他的策略，能够让用户根据自身的业务需求进行选择。</li></ul><h2 id="第6章-hystrix服务容错处理" tabindex="-1">第6章　Hystrix服务容错处理 <a class="header-anchor" href="#第6章-hystrix服务容错处理" aria-label="Permalink to “第6章　Hystrix服务容错处理”">​</a></h2><ul><li>在微服务架构中存在多个可直接调用的服务，这些服务若在调用时出现故障会导致连锁效应，也就是可能会让整个系统变得不可用，这种情况我们称之为<strong>服务雪崩效应</strong>。</li><li>Hystrix是Netflix针对微服务分布式系统采用的<strong>熔断保护中间件</strong>，相当于电路中的保险丝。</li></ul>',8)])])}const _=r(n,[["render",t]]);export{c as __pageData,_ as default};
